<details class="public-axis-filter" <?= ($f['year_from']??'')!==''||($f['year_to']??'')!==''?'open':'' ?>><summary>تاریخ</summary><label>نوع تاریخ<select name="date_kind" aria-label="نوع تاریخ"><option value="martyrdom_date">شهادت</option><option value="birth_date" <?= ($f['date_kind']??'')==='birth_date'?'selected':'' ?>>تولد</option></select></label><label>تقویم<select name="calendar" aria-label="تقویم"><?php foreach(['jalali'=>'شمسی','gregorian'=>'میلادی','hijri'=>'قمری'] as $key=>$text): ?><option value="<?= $key ?>" <?= ($f['calendar']??'jalali')===$key?'selected':'' ?>><?= $text ?></option><?php endforeach ?></select></label><label>از سال<input inputmode="numeric" name="year_from" maxlength="4" value="<?= e($f['year_from']??'') ?>"></label><label>تا سال<input inputmode="numeric" name="year_to" maxlength="4" value="<?= e($f['year_to']??'') ?>"></label><p class="hint">فقط سال شناخته‌شده در همین تقویم؛ ماه و روز نامعلوم حدس زده نمی‌شوند.</p></details>
